//! Order types and structures.

use quant_instruments::InstrumentId;
use serde::{Deserialize, Serialize};

/// Order type specification.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum OrderType {
    Market,
    Limit,
}

/// Order generated by portfolio rebalancing or execution strategies.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Order {
    pub instrument: InstrumentId,
    pub symbol: String,
    pub order_type: OrderType,
    /// Signed order quantity: positive for BUY, negative for SELL.
    pub quantity: f64,
    /// Limit price for limit orders.
    pub limit_price: Option<f64>,
    /// Maximum allowed fraction of bar trading volume (e.g. 0.05 = 5%).
    pub participation_cap: Option<f64>,
    /// Creation timestamp (unix milliseconds/nanoseconds UTC).
    pub as_of: i64,
}

impl Order {
    pub fn market(
        instrument: InstrumentId,
        symbol: impl Into<String>,
        quantity: f64,
        as_of: i64,
    ) -> Self {
        Self {
            instrument,
            symbol: symbol.into(),
            order_type: OrderType::Market,
            quantity,
            limit_price: None,
            participation_cap: Some(0.05),
            as_of,
        }
    }

    pub fn limit(
        instrument: InstrumentId,
        symbol: impl Into<String>,
        quantity: f64,
        limit_price: f64,
        as_of: i64,
    ) -> Self {
        Self {
            instrument,
            symbol: symbol.into(),
            order_type: OrderType::Limit,
            quantity,
            limit_price: Some(limit_price),
            participation_cap: Some(0.05),
            as_of,
        }
    }

    pub fn is_buy(&self) -> bool {
        self.quantity > 1e-8
    }

    pub fn is_sell(&self) -> bool {
        self.quantity < -1e-8
    }
}
